def seed_scorecard(apps, schema_editor):
    """مقادیر اولیه: تنظیمات سراسری، جدول رابط (از کارنامه نمونه)، و فعال‌کردن کارنامه برای معاونت‌ها و مدیریت‌های مستقل."""
    Config = apps.get_model("strategic", "ScorecardConfig")
    Topic = apps.get_model("strategic", "LiaisonTopic")
    Param = apps.get_model("strategic", "LiaisonParam")
    OrgUnit = apps.get_model("strategic", "OrgUnit")
    Management = apps.get_model("strategic", "Management")
    if not Config.objects.exists():
        year, month = 1405, 1
        try:
            import jdatetime
            today = jdatetime.date.today()
            year, month = today.year, today.month
        except Exception:
            pass
        Config.objects.create(
            period_year=year, period_month=month,
            notes=(
                "امتیاز دستیابی به اهداف شاخص‌های سازمان همان امتیاز اعلامی شرکت مادر در کارنامه عملکرد شرکت است.\n"
                "برای اهدافی که تحقق آن‌ها کمتر از ۹۰٪ است، فرم تحلیل عملکرد باید توسط مالک هدف تکمیل و برای دفتر طرح و برنامه ارسال شود."
            ),
        )
    if not Topic.objects.exists():
        seeds = [
            ("پروژه‌ها و برنامه‌های طرح +۱۰۰", [
                "ثبت به‌موقع درصد پیشرفت پروژه‌ها در سامانه مدیریت عملکرد BSC",
                "صحت و دقت اطلاعات ثبت‌شده در سامانه مدیریت عملکرد BSC",
                "حضور اعضای تیم تخصصی پیشبرد مربوطه در جلسات پیشرفت پروژه‌ها",
                "تحویل به‌موقع مستندات پروژه اعم از فرم شناسنامه پروژه، تعریف فعالیت، صورتجلسات، اقدامات و ...",
                "پاسخ‌دهی مناسب رابطین به تماس‌ها و مکاتبات و درخواست‌ها با مدیریت برنامه‌ریزی و نظارت راهبردی",
            ]),
            ("ارزیابی عملکرد (شاخص‌ها)", [
                "ثبت به‌موقع اطلاعات عملکرد در مخزن شاخص‌ها",
                "صحت و دقت اطلاعات ثبت‌شده در مخزن شاخص‌ها",
                "ارسال به‌موقع اطلاعات عملکرد مربوط به شاخص‌های سایپا SBPMS",
                "ارسال به‌موقع گزارشات تحلیلی وضعیت عملکرد شاخص‌ها",
                "پاسخ‌دهی مناسب رابطین به تماس‌ها و مکاتبات و درخواست‌ها با مدیریت برنامه‌ریزی و نظارت راهبردی",
            ]),
        ]
        for i, (title, params) in enumerate(seeds, 1):
            t = Topic.objects.create(title=title, base_score=50, order=i)
            for j, text in enumerate(params, 1):
                Param.objects.create(topic=t, text=text, max_score=10, order=j)
    OrgUnit.objects.filter(kind="deputy").update(has_scorecard=True)
    Management.objects.filter(org_unit__kind="ceo_direct").update(has_scorecard=True)


